import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createTaxRatesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createTaxRatesWorkflow(req.scope)
    .run({
      input: [{
        tax_region_id: "txreg_123",
        name: "Default"
      }]
    })

  res.send(result)
}

